'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useState } from 'react';

import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';

import { ActivityPanel } from './activity-panel';
import { CommentComposer } from './comment-composer';
import { CommentPanel } from './comment-panel';
import { COMMENTS, EVENTS, SUBTASKS, TASK } from './data';
import { heightPresenceOf, RollingCount } from './motion-parts';
import { SubtaskPanel } from './subtask-panel';
import {
  PeopleStack,
  ProgressRing,
  STATUS_NAME,
  StatusGlyph,
} from './work-glyphs';
import {
  addedSubtask,
  doneCountOf,
  dueLabelOf,
  personOf,
  postedComment,
  toggledSubtask,
  type WorkState,
} from './work-model';

type WorkTab = 'subtasks' | 'comments' | 'activity';

const FIRST_STATE: WorkState = {
  subtasks: SUBTASKS,
  comments: COMMENTS,
  events: EVENTS,
};

function isWorkTab(value: unknown): value is WorkTab {
  const isSubtasks = value === 'subtasks';
  const isComments = value === 'comments';
  const isActivity = value === 'activity';
  return isSubtasks || isComments || isActivity;
}

function TaskHeader() {
  const people = TASK.assigneeIds.map(personOf);
  const firstNames = people.map((person) => person.firstName);
  const assigneeNames = firstNames.join(' and ');
  return (
    <header>
      <nav
        aria-label='Breadcrumb'
        className='text-muted-foreground flex items-center gap-1 text-xs'
      >
        <span>{TASK.project}</span>
        <ChevronRightIcon className='size-3' />
        <span className='tabular-nums'>{TASK.key}</span>
      </nav>
      <h1 className='mt-2 text-xl font-semibold text-balance sm:text-2xl'>
        {TASK.title}
      </h1>
      <div className='text-muted-foreground mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 text-[13px]'>
        <span className='text-foreground inline-flex items-center gap-1.5'>
          <StatusGlyph status={TASK.status} />
          {STATUS_NAME[TASK.status]}
        </span>
        <span className='inline-flex items-center gap-2'>
          <PeopleStack people={people} />
          {assigneeNames}
        </span>
        <span className='tabular-nums'>{dueLabelOf(TASK.due)}</span>
      </div>
      <p className='mt-4 text-[13px] leading-relaxed'>{TASK.description}</p>
    </header>
  );
}

export default function TaskDetail03() {
  const shouldReduceMotion = useReducedMotion();
  const [work, setWork] = useState<WorkState>(FIRST_STATE);
  const [tab, setTab] = useState<WorkTab>('subtasks');
  const doneCount = doneCountOf(work.subtasks);
  const total = work.subtasks.length;
  const isCommentsTab = tab === 'comments';

  function change(value: unknown) {
    if (isWorkTab(value)) {
      setTab(value);
    }
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-6 sm:px-8 sm:py-10'>
      <div className='mx-auto max-w-2xl'>
        <TaskHeader />
        <div className='bg-card hairline-ring ring-border mt-6 rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <Tabs value={tab} onValueChange={change} className='gap-0'>
            <div className='px-3 pt-3 sm:px-4 sm:pt-4'>
              <TabsList
                variant='segmented'
                aria-label='Work on this task'
                className='max-w-full'
              >
                <TabsTab value='subtasks'>
                  <span className='hidden sm:inline-flex'>
                    <ProgressRing done={doneCount} total={total} />
                  </span>
                  Sub-tasks
                  <span className='text-muted-foreground flex text-xs tabular-nums'>
                    <RollingCount value={doneCount} />/
                    <RollingCount value={total} />
                  </span>
                </TabsTab>
                <TabsTab value='comments'>
                  Comments
                  <RollingCount
                    value={work.comments.length}
                    className='text-muted-foreground text-xs'
                  />
                </TabsTab>
                <TabsTab value='activity'>
                  Activity
                  <RollingCount
                    value={work.events.length}
                    className='text-muted-foreground text-xs'
                  />
                </TabsTab>
              </TabsList>
            </div>
            <AnimatedSize>
              <div className='px-3 py-3 sm:px-4'>
                <TabsPanel value='subtasks'>
                  <SubtaskPanel
                    subtasks={work.subtasks}
                    onToggle={(subtaskId) =>
                      setWork((current) => toggledSubtask(current, subtaskId))
                    }
                    onAdd={(title) =>
                      setWork((current) => addedSubtask(current, title))
                    }
                  />
                </TabsPanel>
                <TabsPanel value='comments'>
                  <CommentPanel comments={work.comments} />
                </TabsPanel>
                <TabsPanel value='activity'>
                  <ActivityPanel events={work.events} />
                </TabsPanel>
              </div>
            </AnimatedSize>
            <AnimatePresence initial={false}>
              {isCommentsTab && (
                <motion.div
                  key='composer'
                  {...heightPresenceOf(shouldReduceMotion)}
                  className='overflow-hidden'
                >
                  <CommentComposer
                    onSubmit={(body) =>
                      setWork((current) => postedComment(current, body))
                    }
                    className='px-3 pb-3 sm:px-4 sm:pb-4'
                  />
                </motion.div>
              )}
            </AnimatePresence>
          </Tabs>
        </div>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Subtask } from './data';
import { heightPresenceOf } from './motion-parts';
import { PersonAvatar, StrikeTitle } from './work-glyphs';
import { keyOf, personOf } from './work-model';

function SubtaskRow({
  subtask,
  onToggle,
}: {
  subtask: Subtask;
  onToggle: () => void;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <label className='hover:bg-foreground/[0.03] flex h-9 cursor-pointer items-center gap-3 rounded-lg px-2'>
        <Checkbox checked={subtask.isDone} onCheckedChange={onToggle} />
        <span className='text-muted-foreground hidden w-16 shrink-0 text-xs tabular-nums sm:inline'>
          {keyOf(subtask.number)}
        </span>
        <StrikeTitle
          title={subtask.title}
          isDone={subtask.isDone}
          className='flex-1'
        />
        {subtask.assigneeId && (
          <PersonAvatar
            person={personOf(subtask.assigneeId)}
            className='size-5 text-[9px]'
          />
        )}
      </label>
    </motion.li>
  );
}

type SubtaskPanelProps = {
  subtasks: Subtask[];
  onToggle: (subtaskId: string) => void;
  onAdd: (title: string) => void;
};

export function SubtaskPanel({ subtasks, onToggle, onAdd }: SubtaskPanelProps) {
  const [title, setTitle] = useState('');
  const trimmed = title.trim();
  const canAdd = trimmed.length > 0;

  function add(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canAdd) {
      return;
    }
    onAdd(trimmed);
    setTitle('');
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      setTitle('');
    }
  }

  return (
    <div className='flex flex-col gap-1'>
      <ul>
        <AnimatePresence initial={false}>
          {subtasks.map((subtask) => (
            <SubtaskRow
              key={subtask.id}
              subtask={subtask}
              onToggle={() => onToggle(subtask.id)}
            />
          ))}
        </AnimatePresence>
      </ul>
      <form
        onSubmit={add}
        className='hairline-border border-foreground/20 focus-within:border-foreground/35 flex h-9 items-center gap-3 rounded-lg border-dashed ps-2 pe-1.5 transition-colors'
      >
        <PlusIcon className='text-muted-foreground size-4 shrink-0' />
        <input
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          onKeyDown={handleKeyDown}
          aria-label='New sub-task title'
          placeholder='Add a sub-task'
          className='placeholder:text-muted-foreground/75 h-8 min-w-0 flex-1 bg-transparent text-base outline-none md:text-[13px]'
        />
        <Kbd
          aria-hidden='true'
          className={cn(
            'transition-opacity duration-150',
            !canAdd && 'opacity-0'
          )}
        >
          Enter
        </Kbd>
        <button type='submit' className='sr-only'>
          Add sub-task
        </button>
      </form>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import type { TaskComment } from './data';
import { heightPresenceOf } from './motion-parts';
import { CommentText, PersonAvatar } from './work-glyphs';
import { actorNameOf, personOf, relativeTimeOf } from './work-model';

function CommentRow({ comment }: { comment: TaskComment }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='flex gap-3 py-2'>
        <PersonAvatar
          person={personOf(comment.authorId)}
          className='size-7 text-[10px]'
        />
        <div className='min-w-0 flex-1'>
          <p className='flex min-h-7 items-center gap-1.5 text-[13px]'>
            <span className='truncate font-medium'>
              {actorNameOf(comment.authorId)}
            </span>
            <span aria-hidden='true' className='text-muted-foreground'>
              ·
            </span>
            <time
              dateTime={comment.at}
              className='text-muted-foreground shrink-0 text-xs tabular-nums'
            >
              {relativeTimeOf(comment.at)}
            </time>
          </p>
          <CommentText body={comment.body} />
        </div>
      </div>
    </motion.li>
  );
}

export function CommentPanel({ comments }: { comments: TaskComment[] }) {
  const isEmpty = comments.length === 0;

  return (
    <div>
      {isEmpty && (
        <p className='text-muted-foreground py-4 text-center text-[13px]'>
          No comments yet. Write the first one below
        </p>
      )}
      <ul>
        <AnimatePresence initial={false}>
          {comments.map((comment) => (
            <CommentRow key={comment.id} comment={comment} />
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
}

import type { WorkEvent } from './data';
import { EventGlyph } from './work-glyphs';
import { actorNameOf, clockOf, eventDaysOf } from './work-model';

function EventRow({ event }: { event: WorkEvent }) {
  return (
    <li className='flex gap-3 py-1.5'>
      <EventGlyph kind={event.kind} />
      <p className='text-muted-foreground min-w-0 flex-1 pt-0.5 text-[13px] leading-5'>
        <span className='text-foreground font-medium'>
          {actorNameOf(event.actorId)}
        </span>{' '}
        {event.text}
        <time dateTime={event.at} className='ms-2 text-xs tabular-nums'>
          {clockOf(event.at)}
        </time>
      </p>
    </li>
  );
}

export function ActivityPanel({ events }: { events: WorkEvent[] }) {
  const days = eventDaysOf(events);

  return (
    <div className='flex flex-col gap-2'>
      {days.map((day) => (
        <section key={day.key} aria-label={day.label}>
          <h4 className='text-muted-foreground pb-1 text-xs font-medium'>
            {day.label}
          </h4>
          <ul>
            {day.events.map((event) => (
              <EventRow key={event.id} event={event} />
            ))}
          </ul>
        </section>
      ))}
    </div>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { PersonAvatar } from './work-glyphs';
import { currentUser } from './work-model';

type CommentComposerProps = {
  onSubmit: (body: string) => void;
  placeholder?: string;
  className?: string;
};

function isSendKey(event: React.KeyboardEvent<HTMLTextAreaElement>) {
  const isCommand = event.metaKey || event.ctrlKey;
  return isCommand && event.key === 'Enter';
}

export function CommentComposer({
  onSubmit,
  placeholder = 'Leave a comment',
  className,
}: CommentComposerProps) {
  const [body, setBody] = useState('');
  const me = currentUser();
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;

  function submit() {
    if (!canSend) {
      return;
    }
    onSubmit(trimmed);
    setBody('');
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (isSendKey(event)) {
      event.preventDefault();
      submit();
      return;
    }
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.currentTarget.blur();
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={cn('flex items-start gap-3', className)}
    >
      <PersonAvatar person={me} className='mt-1 size-7 text-[10px]' />
      <div className='relative min-w-0 flex-1'>
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
          aria-label={`Comment as ${me.name}`}
          placeholder={placeholder}
          className='min-h-9 py-2 pe-24'
        />
        <Button
          type='submit'
          size='sm'
          disabled={!canSend}
          className='absolute end-1 bottom-1'
        >
          Comment
        </Button>
      </div>
    </form>
  );
}

import {
  CheckIcon,
  CircleDashedIcon,
  ClockIcon,
  ListTreeIcon,
  MessageCircleIcon,
  PlusIcon,
  UserIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Person, StatusId, WorkEventKind } from './data';
import { segmentsOf } from './work-model';

const STATUS_COLOR: Record<StatusId, string> = {
  backlog: 'var(--muted-foreground)',
  todo: 'var(--muted-foreground)',
  in_progress: 'var(--warning)',
  in_review: 'var(--primary)',
  done: 'var(--success)',
};

export const STATUS_NAME: Record<StatusId, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
};

const PIE_RADIUS = 2;

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function StartedShape({ share }: { share: number }) {
  const filled = share * PIE_CIRCUMFERENCE;
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={`${filled} ${PIE_CIRCUMFERENCE}`}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const glyphStyle = { color: STATUS_COLOR[status] } as React.CSSProperties;
  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
    >
      {statusShapeOf(status)}
    </svg>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-6 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

export function PeopleStack({
  people,
  ringClassName = 'ring-background',
}: {
  people: Person[];
  ringClassName?: string;
}) {
  return (
    <span className='flex items-center -space-x-1.5'>
      {people.map((person) => (
        <PersonAvatar
          key={person.id}
          person={person}
          className={cn('size-5 text-[9px] ring-2', ringClassName)}
        />
      ))}
    </span>
  );
}

const RING_RADIUS = 6.5;

const RING_LENGTH = 2 * Math.PI * RING_RADIUS;

function shareOf(done: number, total: number) {
  if (total === 0) {
    return 0;
  }
  return done / total;
}

export function ProgressRing({ done, total }: { done: number; total: number }) {
  const share = shareOf(done, total);
  const isComplete = total > 0 && done === total;
  const dashOffset = RING_LENGTH * (1 - share);
  return (
    <svg viewBox='0 0 16 16' aria-hidden='true' className='size-4 -rotate-90'>
      <circle
        cx='8'
        cy='8'
        r={RING_RADIUS}
        fill='none'
        strokeWidth='2'
        className='stroke-foreground/10'
      />
      <circle
        cx='8'
        cy='8'
        r={RING_RADIUS}
        fill='none'
        strokeWidth='2'
        strokeLinecap='round'
        strokeDasharray={RING_LENGTH}
        strokeDashoffset={dashOffset}
        className={cn(
          'stroke-primary transition-[stroke-dashoffset,stroke] duration-300 ease-(--ease-out-strong)',
          isComplete && 'stroke-success'
        )}
      />
    </svg>
  );
}

/** A title struck from left to right when its sub-task is done. */
export function StrikeTitle({
  title,
  isDone,
  className,
}: {
  title: string;
  isDone: boolean;
  className?: string;
}) {
  return (
    <span
      className={cn(
        'relative min-w-0 truncate text-[13px] transition-colors duration-200',
        isDone && 'text-muted-foreground',
        className
      )}
    >
      {title}
      <span
        aria-hidden='true'
        className={cn(
          'bg-foreground/35 pointer-events-none absolute inset-x-0 top-1/2 h-px origin-left scale-x-0 transition-transform duration-200 ease-(--ease-out-strong)',
          isDone && 'scale-x-100'
        )}
      />
    </span>
  );
}

const EVENT_ICON: Record<WorkEventKind, Icon> = {
  created: PlusIcon,
  status: CircleDashedIcon,
  assignee: UserIcon,
  estimate: ClockIcon,
  subtask: ListTreeIcon,
  comment: MessageCircleIcon,
};

export function EventGlyph({
  kind,
  className,
}: {
  kind: WorkEventKind;
  className?: string;
}) {
  const Glyph = EVENT_ICON[kind];
  return (
    <span
      className={cn(
        'keycap-3d text-muted-foreground relative flex size-6 shrink-0 items-center justify-center rounded-full [&_svg]:size-3',
        className
      )}
    >
      <Glyph />
    </span>
  );
}

export function DoneMark() {
  return (
    <span className='bg-success/15 text-success-foreground flex size-4 items-center justify-center rounded-full'>
      <CheckIcon strokeWidth={3} className='size-2.5' />
    </span>
  );
}

export function CommentText({
  body,
  className,
}: {
  body: string;
  className?: string;
}) {
  const segments = segmentsOf(body);
  return (
    <p
      className={cn(
        'text-[13px] leading-5 [overflow-wrap:anywhere] whitespace-pre-wrap',
        className
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <span
              key={key}
              className='bg-primary/10 text-primary-ink dark:bg-primary/20 rounded-[4px] px-0.5 font-medium'
            >
              {segment.text}
            </span>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
    </p>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

import {
  differenceInCalendarDays,
  differenceInMinutes,
  format,
  parseISO,
} from 'date-fns';

import {
  CURRENT_USER_ID,
  NOW,
  PEOPLE,
  TEAM_KEY,
  type Subtask,
  type TaskComment,
  type WorkEvent,
} from './data';

export type WorkState = {
  subtasks: Subtask[];
  comments: TaskComment[];
  events: WorkEvent[];
};

export type EventDay = {
  key: string;
  label: string;
  events: WorkEvent[];
};

const MINUTES_PER_HOUR = 60;

const FIRST_FREE_NUMBER = 230;

let createdCount = 0;

export function nextSeq() {
  createdCount += 1;
  return createdCount;
}

function nextIdOf(prefix: string) {
  return `${prefix}-${nextSeq()}`;
}

export function personOf(id: string) {
  const found = PEOPLE.find((person) => person.id === id);
  if (found) {
    return found;
  }
  return PEOPLE[0];
}

export function currentUser() {
  return personOf(CURRENT_USER_ID);
}

export function actorNameOf(id: string) {
  if (id === CURRENT_USER_ID) {
    return 'You';
  }
  return personOf(id).name;
}

export function keyOf(number: number) {
  return `${TEAM_KEY}-${number}`;
}

export function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `${count} ${singular}`;
  }
  return `${count} ${plural}`;
}

export function doneCountOf(subtasks: Subtask[]) {
  return subtasks.filter((subtask) => subtask.isDone).length;
}

function daysBeforeNow(iso: string) {
  return differenceInCalendarDays(parseISO(NOW), parseISO(iso));
}

export function relativeTimeOf(iso: string) {
  const minutes = differenceInMinutes(parseISO(NOW), parseISO(iso));
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return `${minutes}m ago`;
  }
  const days = daysBeforeNow(iso);
  if (days === 0) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return `${hours}h ago`;
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'MMM d');
}

export function clockOf(iso: string) {
  return format(parseISO(iso), 'HH:mm');
}

export function dueLabelOf(iso: string) {
  const days = -daysBeforeNow(iso);
  if (days === 0) {
    return 'Due today';
  }
  if (days === 1) {
    return 'Due tomorrow';
  }
  if (days > 1) {
    return `Due in ${days} days`;
  }
  return `${Math.abs(days)} days late`;
}

function dayLabelOf(iso: string) {
  const days = daysBeforeNow(iso);
  if (days === 0) {
    return 'Today';
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'EEEE, MMM d');
}

/** Newest day first, newest event first inside each day. */
export function eventDaysOf(events: WorkEvent[]) {
  const sorted = [...events].sort((first, second) =>
    second.at.localeCompare(first.at)
  );
  const days: EventDay[] = [];
  for (const event of sorted) {
    const key = event.at.slice(0, 10);
    const last = days.at(-1);
    const isSameDay = last?.key === key;
    if (isSameDay) {
      last.events.push(event);
      continue;
    }
    days.push({ key, label: dayLabelOf(event.at), events: [event] });
  }
  return days;
}

function toggleEventOf(subtask: Subtask): WorkEvent {
  let verb = 'reopened';
  if (subtask.isDone) {
    verb = 'completed';
  }
  return {
    id: `toggle-${subtask.id}`,
    kind: 'subtask',
    actorId: CURRENT_USER_ID,
    at: NOW,
    text: `${verb} ${keyOf(subtask.number)} ${subtask.title}`,
    seq: nextSeq(),
  };
}

/** A sub-task checked then unchecked in the same visit leaves one line in the log, not two. */
function withEvent(events: WorkEvent[], event: WorkEvent) {
  const others = events.filter((item) => item.id !== event.id);
  return [...others, event];
}

export function toggledSubtask(state: WorkState, subtaskId: string) {
  const target = state.subtasks.find((subtask) => subtask.id === subtaskId);
  if (!target) {
    return state;
  }
  const toggled: Subtask = { ...target, isDone: !target.isDone };
  const subtasks = state.subtasks.map((subtask) => {
    if (subtask.id !== subtaskId) {
      return subtask;
    }
    return toggled;
  });
  const events = withEvent(state.events, toggleEventOf(toggled));
  const next: WorkState = { ...state, subtasks, events };
  return next;
}

function nextNumberOf(subtasks: Subtask[]) {
  const numbers = subtasks.map((subtask) => subtask.number);
  return Math.max(FIRST_FREE_NUMBER, ...numbers) + 1;
}

export function addedSubtask(state: WorkState, title: string) {
  const number = nextNumberOf(state.subtasks);
  const subtask: Subtask = {
    id: nextIdOf('subtask'),
    number,
    title,
    isDone: false,
  };
  const event: WorkEvent = {
    id: nextIdOf('event'),
    kind: 'subtask',
    actorId: CURRENT_USER_ID,
    at: NOW,
    text: `added ${keyOf(number)} ${title}`,
    seq: nextSeq(),
  };
  const next: WorkState = {
    ...state,
    subtasks: [...state.subtasks, subtask],
    events: [...state.events, event],
  };
  return next;
}

export function postedComment(state: WorkState, body: string) {
  const comment: TaskComment = {
    id: nextIdOf('comment'),
    authorId: CURRENT_USER_ID,
    at: NOW,
    body,
    seq: nextSeq(),
  };
  return withComment(state, comment);
}

export function withComment(state: WorkState, comment: TaskComment) {
  const event: WorkEvent = {
    id: nextIdOf('event'),
    kind: 'comment',
    actorId: comment.authorId,
    at: comment.at,
    text: 'commented',
    seq: comment.seq,
  };
  const next: WorkState = {
    ...state,
    comments: [...state.comments, comment],
    events: [...state.events, event],
  };
  return next;
}

export type Segment = {
  text: string;
  isMention: boolean;
};

const MENTION_TOKENS = PEOPLE.map((person) => `@${person.name}`);

function pushPlain(segments: Segment[], text: string) {
  if (text.length === 0) {
    return;
  }
  segments.push({ text, isMention: false });
}

/** Splits a comment into plain text and mentions of known people, written "@First Last". */
export function segmentsOf(text: string) {
  const segments: Segment[] = [];
  let plain = '';
  let index = 0;
  while (index < text.length) {
    const token = MENTION_TOKENS.find((candidate) =>
      text.startsWith(candidate, index)
    );
    if (token) {
      pushPlain(segments, plain);
      segments.push({ text: token, isMention: true });
      plain = '';
      index += token.length;
      continue;
    }
    plain += text[index];
    index += 1;
  }
  pushPlain(segments, plain);
  return segments;
}

